CREATE TRIGGER current_base_resume_draft_parent_same_source BEFORE INSERT ON current_base_resume_drafts WHEN NEW.parent_draft_id IS NOT NULL AND (SELECT source_id FROM current_base_resume_drafts WHERE id = NEW.parent_draft_id) <> NEW.source_id BEGIN SELECT RAISE(ABORT, 'draft parent must share source'); END;
CREATE TRIGGER current_base_resume_version_source_matches_draft BEFORE INSERT ON current_base_resume_versions WHEN (SELECT source_id FROM current_base_resume_drafts WHERE id = NEW.draft_id) <> NEW.source_id BEGIN SELECT RAISE(ABORT, 'version source must match draft source'); END;
CREATE TRIGGER current_base_resume_proposal_revision_linear BEFORE INSERT ON current_base_resume_proposal_revisions WHEN NEW.parent_revision_id IS NOT NULL AND ((SELECT proposal_id FROM current_base_resume_proposal_revisions WHERE id = NEW.parent_revision_id) <> NEW.proposal_id OR EXISTS (SELECT 1 FROM current_base_resume_proposal_revisions WHERE parent_revision_id = NEW.parent_revision_id)) BEGIN SELECT RAISE(ABORT, 'proposal revision must extend one parent'); END;
